import { compandStream } from "@audio/dynamics-compand";
import { type DeviceState, defineDevice } from "@audio-ui/core/device";
import { COMPANDER_KERNELS } from "@/components/audio-ui/devices/compander/kernels";
import { manifestWorklet } from "@/lib/manifest-worklet";

/** The levels in, in dB, whose levels out the compander's points set: the manifest's own. */
export const COMPANDER_POINTS_DB = [-90, -60, -20, 0] as const;
/** Each point's parameter, by its level in. */
export const COMPANDER_POINTS = [
  "out0Db",
  "out1Db",
  "out2Db",
  "out3Db",
] as const;

/**
 * A compander as a device: the multi-segment compander of
 * `@audio/dynamics-compand`, its transfer curve set by four points, with no
 * panel and no audio in it. One curve does a compressor's work, an
 * expander's or a gate's.
 */
export const companderDevice = defineDevice({
  description:
    "Draws its own transfer curve: the level out at -90, -60, -20 and 0 dB in, in straight lines between them. A point under the straight line of a clean sound turns the sound down at that level, one over it turns it up: one curve brings the loud parts down, lifts the quiet ones or closes on the noise. The attack and the release say how fast it follows the level.",
  id: "audioui.compander",
  name: "Compander",
  parameters: [
    { default: true, id: "enabled", kind: "toggle", label: "On" },
    {
      default: -90,
      id: "out0Db",
      label: "At -90 dB",
      max: 0,
      min: -90,
      step: 0.5,
      unit: "dB",
    },
    {
      default: -60,
      id: "out1Db",
      label: "At -60 dB",
      max: 0,
      min: -90,
      step: 0.5,
      unit: "dB",
    },
    {
      default: -20,
      id: "out2Db",
      label: "At -20 dB",
      max: 0,
      min: -90,
      step: 0.5,
      unit: "dB",
    },
    {
      default: -8,
      id: "out3Db",
      label: "At 0 dB",
      max: 0,
      min: -90,
      step: 0.5,
      unit: "dB",
    },
    {
      default: 5,
      id: "attackMs",
      label: "Attack",
      max: 200,
      min: 0.1,
      scale: "log",
      step: 0.1,
      unit: "ms",
    },
    {
      default: 200,
      id: "releaseMs",
      label: "Release",
      max: 2000,
      min: 1,
      scale: "log",
      step: 1,
      unit: "ms",
    },
  ],
});

export type CompanderState = DeviceState<typeof companderDevice.parameters>;

/** The numbers that go on the worklet for a state, in the manifest's units. Off, the sound goes round it. */
export function companderSettings(state: CompanderState) {
  return {
    modelParams: {
      attack: state.attackMs,
      out0: state.out0Db,
      out1: state.out1Db,
      out2: state.out2Db,
      out3: state.out3Db,
      release: state.releaseMs,
    },
    wet: state.enabled ? 1 : 0,
  };
}

/** The rate the compander runs at to be measured: a steady level settles the same at any rate, and this one is cheap. */
const CURVE_RATE = 1000;

/**
 * The curve a state plays: the level out in dB for a level in, once it has
 * settled, measured from the package's own stream run on a steady level for
 * ten of its attacks, a decibel apart, read in between in a line.
 */
export function companderCurve(state: CompanderState) {
  if (!state.enabled) {
    return (inputDb: number) => inputDb;
  }
  const points = COMPANDER_POINTS_DB.map((inDb, index): [number, number] => [
    inDb,
    state[COMPANDER_POINTS[index] ?? "out0Db"],
  ]);
  const levels: number[] = [];
  const block = new Float32Array(
    Math.max(512, Math.ceil(((10 * state.attackMs) / 1000) * CURVE_RATE))
  );
  for (let db = -90; db <= 0; db += 1) {
    const stream = compandStream({
      attack: state.attackMs,
      points,
      release: state.releaseMs,
      sampleRate: CURVE_RATE,
    });
    block.fill(10 ** (db / 20));
    const out = stream.write(block);
    levels.push(20 * Math.log10(Math.abs(out.at(-1) ?? 0) + 1e-30));
  }
  return (inputDb: number) => {
    const at = Math.min(Math.max(inputDb + 90, 0), levels.length - 1);
    const below = Math.min(Math.floor(at), levels.length - 2);
    const from = levels[below] ?? 0;
    const to = levels[below + 1] ?? from;
    return from + (at - below) * (to - from) + Math.min(0, inputDb + 90);
  };
}

/**
 * The source of the compander's `AudioWorklet`, processor
 * `audioui-compander`: the manifest of `@audio/dynamics-compand`, played by
 * `manifestWorklet`. Every parameter makes it again.
 */
export const COMPANDER_WORKLET = manifestWorklet({
  kernels: COMPANDER_KERNELS,
  models: { compander: "compand" },
  processor: "audioui-compander",
});

/**
 * audio.js kernels, each module as published, in its own scope, for an
 * `AudioWorklet`, which cannot import them:
 * - `@audio/dynamics-envelope` 0.1.4 (MIT, Dmitry Iv.): `timeCoef`, as `module0`
 * - `@audio/dynamics-envelope` 0.1.4 (MIT, Dmitry Iv.): `envelope`, as `module1`
 * - `@audio/dynamics-compand` 0.1.7 (MIT, Dmitry Iv.): `writer`, `concat`, `db2lin`, `lin2db`, as `module2`
 * - `@audio/dynamics-compand` 0.1.7 (MIT, Dmitry Iv.): `compandStream`, as `module3`
 * - `@audio/dynamics-compand` 0.1.7 (MIT, Dmitry Iv.): `compand`
 */
export const COMPANDER_KERNELS = `const module0 = (() => {
// Local helpers (inlined family convention — no shared-dep package).

// One-pole smoothing coefficient: y[n] = c·y[n-1] + (1-c)·x[n]. ms → coefficient.
function timeCoef(ms, sampleRate) {
  if (ms <= 0) return 0
  return Math.exp(-1 / (ms * 0.001 * sampleRate))
}

return { timeCoef };
})();

const module1 = (() => {
const { timeCoef } = module0;

// Branching one-pole envelope follower. Returns a stateful per-sample detector.
// Separate attack and release time constants; the classic feed-forward compressor
// topology. Peak or RMS detection selectable.
function envelope(opts = {}) {
  // sampleRate is this family's documented key; fs accepted too — half the ecosystem
  // (and dynamics' own fs-named atoms: multiband, leveler, transient-shaper) passes fs,
  // and silently falling back to 44100 skews ballistics at any other rate.
  let sr = opts.sampleRate ?? opts.fs ?? 44100
  let aa = timeCoef(opts.attack ?? 5, sr)
  let ar = timeCoef(opts.release ?? 50, sr)
  let detector = opts.detector || 'peak'
  let rmsWin = Math.max(1, opts.rmsWindow || 256)

  let rmsBuf = detector === 'rms' ? new Float32Array(rmsWin) : null
  let rmsSum = 0
  let rmsIdx = 0
  let env = 0

  return function detect(x) {
    let mag
    if (detector === 'rms') {
      let sq = x * x
      rmsSum += sq - rmsBuf[rmsIdx]
      rmsBuf[rmsIdx] = sq
      rmsIdx = (rmsIdx + 1) % rmsWin
      mag = Math.sqrt(Math.max(0, rmsSum / rmsWin))
    } else {
      mag = x < 0 ? -x : x
    }
    let c = mag > env ? aa : ar
    env = c * env + (1 - c) * mag
    return env
  }
}

return { envelope };
})();

const module2 = (() => {
// Local helpers (inlined family convention — no shared-dep package).

// Wrap { write, flush } into a single callable: write(chunk) → process, write() → flush.
function writer(s) {
  return (chunk) => chunk ? s.write(chunk) : s.flush()
}

function concat(a, b) {
  if (!b || !b.length) return a
  if (!a.length) return b
  let out = new Float32Array(a.length + b.length)
  out.set(a)
  out.set(b, a.length)
  return out
}

// e^(dB·ln10/20) and ln·20/ln10, not 10^(dB/20) and 20·log10: half the cost in V8 (exp and log take ~9 ns, pow
// and log10 ~17-19), a few double ulps from them, far under a float32 ulp.
const db2lin = (db) => Math.exp(db * (Math.LN10 / 20))

const lin2db = (lin) => 20 / Math.LN10 * Math.log(Math.max(Math.abs(lin), 1e-10))

return { writer, concat, db2lin, lin2db };
})();

const module3 = (() => {
const { envelope } = module1;
const { writer, concat, db2lin, lin2db } = module2;

// Multi-segment compander (SoX \`compand\`). Arbitrary piecewise-linear transfer
// in dB. A single curve unifies compression, expansion and gating: points below
// the identity line reduce loud parts; points above raise quiet parts.
function compand(data, opts) {
  if (!(data instanceof Float32Array)) return writer(compandStream(data))
  let s = compandStream(opts)
  return concat(s.write(data), s.flush())
}

function compandStream(opts = {}) {
  // Points: [[inDb, outDb], ...]. Default = mild compression above -20 dB.
  let points = (opts.points || [[-90, -90], [-60, -60], [-20, -20], [0, -8]])
    .slice().sort((a, b) => a[0] - b[0])
  let env = envelope({ ...opts, attack: opts.attack ?? 5, release: opts.release ?? 200 })

  return {
    write(chunk) {
      let out = new Float32Array(chunk.length)
      for (let i = 0; i < chunk.length; i++) {
        let x = chunk[i]
        let lvl = lin2db(env(x))
        let mapped = transfer(points, lvl)
        out[i] = x * db2lin(mapped - lvl)
      }
      return out
    },
    flush() { return new Float32Array(0) }
  }
}

function transfer(points, x) {
  if (x <= points[0][0]) return points[0][1] + (x - points[0][0])
  if (x >= points[points.length - 1][0]) {
    let [xE, yE] = points[points.length - 1]
    return yE + (x - xE)
  }
  for (let i = 1; i < points.length; i++) {
    let [x1, y1] = points[i]
    if (x <= x1) {
      let [x0, y0] = points[i - 1]
      let t = (x - x0) / (x1 - x0)
      return y0 + t * (y1 - y0)
    }
  }
  return x
}

return { compandStream, default: compand };
})();

const compand = (() => {
const { compandStream } = module3;
// atom manifest — wraps the SoX-style compand kernel per @audio/compile CONTRACT.
// The kernel's transfer curve is an arbitrary array of [inDb, outDb] points — arrays
// aren't a valid CONTRACT param type (number/enum/bool only). Scalarized: the input
// breakpoints stay fixed at the kernel's own default shape (-90/-60/-20/0 dB) and the
// four output levels become restart-flagged number params, assembled into a \`points\`
// array only at construction (stream-per-channel style, like the gate pilot).

const IN_DB = [-90, -60, -20, 0]

const compand = (ctx) => {
	const streams = []
	const opts = {
		sampleRate: ctx.sampleRate,
		points: IN_DB.map((inDb, i) => [inDb, ctx.params[\`out\${i}\`][0]]),
		attack: ctx.params.attack[0],
		release: ctx.params.release[0],
	}
	for (let c = 0, N = ctx.maxChannels ?? 8; c < N; c++) streams.push(compandStream(opts))
	return (inputs, outputs) => {
		const inp = inputs[0], out = outputs[0]
		if (!inp || !inp.length) return
		for (let c = 0; c < inp.length; c++) out[c].set(streams[c].write(inp[c]))
	}
}
compand.channels = 'any'
compand.tail = 0
compand.params = {
	out0:    { type: 'number', min: -90, max: 0, default: -90, unit: 'dB', flags: ['restart'] },
	out1:    { type: 'number', min: -90, max: 0, default: -60, unit: 'dB', flags: ['restart'] },
	out2:    { type: 'number', min: -90, max: 0, default: -20, unit: 'dB', flags: ['restart'] },
	out3:    { type: 'number', min: -90, max: 0, default: -8, unit: 'dB', flags: ['restart'] },
	attack:  { type: 'number', min: 0.1, max: 200, default: 5, unit: 'ms', flags: ['restart'] },
	release: { type: 'number', min: 1, max: 2000, default: 200, unit: 'ms', flags: ['restart'] },
}

return compand;
})();
`;
